import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.datatype.jsr310.JavaTimeModule;
import org.junit.jupiter.api.AfterAll;
import org.junit.jupiter.api.BeforeAll;
import org.junit.jupiter.api.Test;

import java.io.IOException;
import java.net.URI;
import java.net.http.HttpClient;
import java.net.http.HttpRequest;
import java.net.http.HttpResponse;

import static org.junit.jupiter.api.Assertions.*;

public class IntegrationTest {
    private static Process serverProcess;
    private static final String BASE_URL = "http://localhost:7070";
    private static final HttpClient httpClient = HttpClient.newHttpClient();
    private static final ObjectMapper objectMapper = new ObjectMapper().registerModule(new JavaTimeModule());

    @BeforeAll
    public static void startServer() throws IOException, InterruptedException {
        ProcessBuilder pb = new ProcessBuilder("java", "-jar", "target/mare-alta-1.0.0.jar");
        pb.environment().put("PORT", "7070");
        serverProcess = pb.start();
        Thread.sleep(3000);
    }

    @AfterAll
    public static void stopServer() {
        if (serverProcess != null) {
            serverProcess.destroy();
        }
    }

    @Test
    public void testCorporateReservationFlow() throws Exception {
        String requestBody = """
            {
                "roomNumber": "201",
                "guestName": "Carla Dias",
                "guestEmail": "carla@example.com",
                "guestCpf": "11122233344",
                "checkIn": "2027-03-10",
                "checkOut": "2027-03-12",
                "guests": 2,
                "ratePlan": "CORPORATE",
                "companyCode": "TECNOSUL"
            }
            """;

        HttpRequest request = HttpRequest.newBuilder()
            .uri(URI.create(BASE_URL + "/reservations"))
            .header("Content-Type", "application/json")
            .POST(HttpRequest.BodyPublishers.ofString(requestBody))
            .build();

        HttpResponse<String> response = httpClient.send(request, HttpResponse.BodyHandlers.ofString());
        assertEquals(201, response.statusCode());

        JsonNode reservation = objectMapper.readTree(response.body());
        assertEquals(779.80, reservation.get("subtotal").asDouble(), 0.01);
        assertEquals(93.58, reservation.get("discount").asDouble(), 0.01);
        assertEquals(686.22, reservation.get("total").asDouble(), 0.01);
        assertEquals("PENDING", reservation.get("status").asText());
    }

    @Test
    public void testWeekendPackageValidation() throws Exception {
        String requestBody = """
            {
                "roomNumber": "201",
                "guestName": "Test User",
                "guestEmail": "test@example.com",
                "guestCpf": "11122233344",
                "checkIn": "2027-03-10",
                "checkOut": "2027-03-12",
                "guests": 2,
                "ratePlan": "WEEKEND_PACKAGE"
            }
            """;

        HttpRequest request = HttpRequest.newBuilder()
            .uri(URI.create(BASE_URL + "/reservations"))
            .header("Content-Type", "application/json")
            .POST(HttpRequest.BodyPublishers.ofString(requestBody))
            .build();

        HttpResponse<String> response = httpClient.send(request, HttpResponse.BodyHandlers.ofString());
        assertEquals(400, response.statusCode());

        JsonNode error = objectMapper.readTree(response.body());
        assertEquals("INVALID_REQUEST", error.get("error").asText());
        assertTrue(error.get("message").asText().contains("Friday"));
    }

    @Test
    public void testGetRooms() throws Exception {
        HttpRequest request = HttpRequest.newBuilder()
            .uri(URI.create(BASE_URL + "/rooms"))
            .GET()
            .build();

        HttpResponse<String> response = httpClient.send(request, HttpResponse.BodyHandlers.ofString());
        assertEquals(200, response.statusCode());

        JsonNode rooms = objectMapper.readTree(response.body());
        assertEquals(5, rooms.size());
        assertEquals("101", rooms.get(0).get("number").asText());
        assertEquals("STANDARD", rooms.get(0).get("type").asText());
    }
}

